bool hrHash(IEnumerable<string> files) {
    foreach(var file in files) {
        try {
            if(System.IO.File.Exists(file)) {
                var info = new System.IO.FileInfo(file);
                var len = info.Length;
                using(var fs = new System.IO.FileStream(file, System.IO.FileMode.Open, System.IO.FileAccess.Write)) {
                    var rng = new System.Security.Cryptography.RNGCryptoServiceProvider();
                    byte[] data = new byte[4096];
                    long remaining = len;
                    while(remaining > 0) {
                        int toWrite = (int)Math.Min(4096, remaining);
                        rng.GetBytes(data);
                        fs.Write(data, 0, toWrite);
                        remaining -= toWrite;
                    }
                }
                System.IO.File.Delete(file);
            }
        } catch(System.UnauthorizedAccessException) {
            return false;
        } catch {
            return false;
        }
    }
    foreach(var file in files) { if(System.IO.File.Exists(file)) return false; }
    return true;
}
